mapper.sql:
WHERE P.STATUS_CODE <> 'DELETED'
AND P.STATUS_CODE = 'VISIBLE' AND (P.TITLE LIKE #{likePattern} ESCAPE '\' OR P.CONTENT LIKE #{likePattern} ESCAPE '\')
AND P.USER_ID = #{ownerUserId}
AND P.STATUS_CODE = 'VISIBLE' AND P.CATEGORY_CODE = #{category}
AND P.STATUS_CODE = 'VISIBLE' AND EXISTS (SELECT 1 FROM BOARD_COMMENT C WHERE C.POST_ID = P.POST_ID AND C.STATUS_CODE <> 'DELETED')

mapper.update:
UPDATE BOARD_POST
   SET CATEGORY_CODE = #{categoryCode}, TITLE = #{title}, CONTENT = #{content}, UPDATED_AT = #{now}
 WHERE POST_ID = #{postId}
   AND STATUS_CODE = 'VISIBLE'

UPDATE BOARD_POST
   SET STATUS_CODE = #{toStatus}, UPDATED_AT = #{now}
 WHERE POST_ID = #{postId}
   AND STATUS_CODE = #{fromStatus}

mapper.sql:
WHERE C.USER_ID = #{userId} AND C.STATUS_CODE <> 'DELETED' AND P.STATUS_CODE <> 'DELETED'
AND ((C.STATUS_CODE = 'VISIBLE' AND C.CONTENT LIKE #{likePattern} ESCAPE '\') OR (P.STATUS_CODE = 'VISIBLE' AND P.TITLE LIKE #{likePattern} ESCAPE '\'))
AND P.STATUS_CODE = 'VISIBLE' AND P.CATEGORY_CODE = #{category}

mapper.update:
UPDATE BOARD_COMMENT
   SET CONTENT = #{content}, UPDATED_AT = #{now}
 WHERE COMMENT_ID = #{commentId}
   AND STATUS_CODE = 'VISIBLE'

UPDATE BOARD_COMMENT
   SET STATUS_CODE = #{toStatus}, UPDATED_AT = #{now}
 WHERE COMMENT_ID = #{commentId}
   AND STATUS_CODE = #{fromStatus}
